#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { Linter } = require('eslint');

const ROOT = path.resolve(__dirname, '..');
const CODE_EXTENSIONS = new Set(['.cjs', '.js', '.jsx', '.mjs']);
const SCANNED_EXTENSIONS = new Set([...CODE_EXTENSIONS, '.html', '.json', '.md']);

// Current copy that a client, attendee, speaker, event staff member, or CCM
// operator can encounter. Historical plans, architecture records, fixtures,
// generated files, legal text, and tests are outside this check.
const ROOT_FILES = Object.freeze([
  'README.md',
  'docs/index.html',
  'docs/ADMIN_GUIDE.md',
  'docs/CLIENT_ONBOARDING.md',
  'docs/DEPLOY_RUNBOOK.md',
  'docs/POSTMARK_PROVISIONING.md',
  'docs/EVENTBRITE_VERIFICATION.md',
  'scripts/lib/demo-event.cjs',
  'scripts/lib/seed.cjs',
]);

const RECURSIVE_ROOTS = Object.freeze([
  'apps/web/src',
  'functions/src',
  'docs/handbook',
  'design/tokens/presets',
]);

const BLOCKED_RULES = Object.freeze([
  {
    id: 'stock-promotion',
    pattern:
      /\b(?:seamless(?:ly)?|robust|effortless(?:ly)?|elevate(?:s|d|ing)?|empower(?:s|ed|ing)?|delve(?:s|d|ing)?|transformative|revolutionary|streamlined)\b|\bunlock(?:s|ed|ing)?\b(?=\s+(?:(?:the|your|our|new|more|full|untapped)\s+){0,3}(?:potential|possibilit(?:y|ies)|power|value|insights?|opportunit(?:y|ies)|growth|impact|benefits?|capabilit(?:y|ies)|experience|future)\b)/giu,
    guidance: 'State the action, result, or limit instead.',
  },
  {
    id: 'marketing-superlative',
    pattern:
      /\b(?:cutting[- ]edge|game[- ]changing|world[- ]class|best[- ]in[- ]class|AI[- ]powered)\b/giu,
    guidance: 'Replace the claim with a specific supported fact.',
  },
  {
    id: 'rhetorical-frame',
    pattern:
      /\b(?:not just|more than just|whether you(?: are|['’]re)|in today(?:'|’)?s|at its core)\b/giu,
    guidance: 'Start with the required fact or instruction.',
  },
  {
    id: 'assistant-meta',
    pattern:
      /\b(?:AI assistant|AI[- ]generated|generated by AI|Claude(?: Code)?|vibe[- ]coded)\b/giu,
    guidance: 'Remove process commentary from current user-facing copy.',
  },
  {
    id: 'design-metaphor',
    pattern:
      /\b(?:reads? as (?:a|an|the|edited|generated)|story (?:reads|written)|on its feet|paper of record|on a good day|wears|dressed in)\b/giu,
    guidance: 'Describe the visible layout or behavior directly.',
  },
  {
    id: 'filler',
    pattern: /\b(?:simply|obviously|of course)\b/giu,
    guidance: 'Delete the filler word or state the reason.',
  },
]);

function normalizePath(relativePath) {
  return relativePath.split(path.sep).join('/');
}

function isExcluded(relativePath) {
  const normalized = normalizePath(relativePath);
  return (
    normalized.includes('/generated/') ||
    normalized.includes('/__tests__/') ||
    normalized.includes('/__fixtures__/') ||
    normalized.startsWith('docs/plans/') ||
    normalized.startsWith('docs/adr/') ||
    normalized.startsWith('docs/architecture/') ||
    normalized.startsWith('functions/vendor/') ||
    normalized === 'design/tokens/presets/README.md' ||
    normalized === 'apps/web/src/setupTests.js' ||
    normalized === 'apps/web/src/admin/presetCopy.js' ||
    /(?:^|\/)(?:dist|node_modules|coverage)\//u.test(normalized) ||
    /\.(?:test|spec)\.[^.]+$/u.test(normalized)
  );
}

function walk(relativeRoot) {
  const absoluteRoot = path.join(ROOT, relativeRoot);
  if (!fs.existsSync(absoluteRoot)) return [];
  const files = [];

  for (const entry of fs.readdirSync(absoluteRoot, { withFileTypes: true })) {
    const child = path.join(relativeRoot, entry.name);
    if (entry.isDirectory()) files.push(...walk(child));
    else if (
      entry.isFile() &&
      SCANNED_EXTENSIONS.has(path.extname(entry.name)) &&
      !isExcluded(child)
    ) {
      files.push(child);
    }
  }

  return files;
}

function collectFiles() {
  const files = new Set();

  for (const relativePath of ROOT_FILES) {
    if (fs.existsSync(path.join(ROOT, relativePath)) && !isExcluded(relativePath)) {
      files.add(relativePath);
    }
  }

  for (const relativeRoot of RECURSIVE_ROOTS) {
    for (const relativePath of walk(relativeRoot)) files.add(relativePath);
  }

  return [...files].sort();
}

function addFragment(fragments, text, startLine, sourceText = text) {
  if (typeof text !== 'string' || !/[\p{L}\p{N}]/u.test(text)) return;
  fragments.push({ text, startLine, sourceText });
}

function skipStringLiteral(node) {
  const parent = node.parent;
  if (!parent) return false;
  if (
    (parent.type === 'ImportDeclaration' ||
      parent.type === 'ExportNamedDeclaration' ||
      parent.type === 'ExportAllDeclaration') &&
    parent.source === node
  ) {
    return true;
  }
  if (parent.type === 'ImportExpression' && parent.source === node) return true;
  if (parent.type === 'Property' && parent.key === node && !parent.computed) return true;
  return parent.type === 'ExpressionStatement' && Boolean(parent.directive);
}

function extractCodeFragments(source, relativePath) {
  const fragments = [];
  const linter = new Linter({ configType: 'eslintrc' });
  linter.defineRule('collect-user-copy', {
    meta: { schema: [] },
    create(context) {
      const sourceCode = context.sourceCode ?? context.getSourceCode();
      const addNodeFragment = (node, text) => {
        addFragment(
          fragments,
          text,
          node.loc.start.line,
          sourceCode.getText(node),
        );
      };

      return {
        Literal(node) {
          if (typeof node.value !== 'string' || skipStringLiteral(node)) return;
          addNodeFragment(node, node.value);
        },
        TemplateElement(node) {
          addNodeFragment(node, node.value.cooked ?? node.value.raw);
        },
        JSXText(node) {
          addNodeFragment(node, node.value);
        },
      };
    },
  });

  const messages = linter.verify(
    source,
    {
      parserOptions: {
        ecmaVersion: 'latest',
        sourceType: 'module',
        ecmaFeatures: { jsx: true },
      },
      rules: { 'collect-user-copy': 'error' },
    },
    { filename: relativePath },
  );
  const fatal = messages.find((message) => message.fatal);
  if (fatal) {
    throw new Error(
      `${relativePath}:${fatal.line ?? 1}:${fatal.column ?? 1}: ${fatal.message}`,
    );
  }

  return fragments;
}

function maskNonProse(source, patterns) {
  let masked = source;
  for (const pattern of patterns) {
    masked = masked.replace(pattern, (match) => match.replace(/[^\n]/gu, ' '));
  }
  return masked;
}

function extractMarkdownFragments(source) {
  return [
    {
      text: maskNonProse(source, [
        /<!--[\s\S]*?-->/gu,
        /```[\s\S]*?```/gu,
        /~~~[\s\S]*?~~~/gu,
        /`[^`\n]*`/gu,
      ]),
      startLine: 1,
    },
  ];
}

function extractHtmlFragments(source) {
  return [
    {
      text: maskNonProse(source, [
        /<!--[\s\S]*?-->/gu,
        /<script\b[^>]*>[\s\S]*?<\/script>/giu,
        /<style\b[^>]*>[\s\S]*?<\/style>/giu,
      ]),
      startLine: 1,
    },
  ];
}

function lineNumberAt(source, index) {
  let line = 1;
  for (let cursor = 0; cursor < index; cursor += 1) {
    if (source[cursor] === '\n') line += 1;
  }
  return line;
}

function locateJsonString(source, key, value, usedValueIndexes) {
  const keyToken = JSON.stringify(key);
  const valueToken = JSON.stringify(value);
  let keyIndex = source.indexOf(keyToken);

  while (keyIndex !== -1) {
    const colon = source.indexOf(':', keyIndex + keyToken.length);
    if (colon === -1) break;
    let valueIndex = colon + 1;
    while (/\s/u.test(source[valueIndex])) valueIndex += 1;
    if (
      source.startsWith(valueToken, valueIndex) &&
      !usedValueIndexes.has(valueIndex)
    ) {
      usedValueIndexes.add(valueIndex);
      return {
        text: value,
        startLine: lineNumberAt(source, valueIndex),
        sourceText: valueToken,
      };
    }
    keyIndex = source.indexOf(keyToken, keyIndex + keyToken.length);
  }

  throw new Error(`Could not locate rendered preset field ${key}.`);
}

function extractPresetFragments(source, relativePath) {
  let preset;
  try {
    preset = JSON.parse(source);
  } catch (error) {
    throw new Error(`${relativePath}: invalid JSON: ${error.message}`);
  }

  const fragments = [];
  const usedValueIndexes = new Set();
  const addField = (object, key) => {
    const value = object?.[key];
    if (typeof value !== 'string') return;
    fragments.push(locateJsonString(source, key, value, usedValueIndexes));
  };

  addField(preset, 'label');
  addField(preset, 'summary');
  addField(preset, 'bestFor');
  for (const option of Object.values(preset.options || {})) {
    addField(option, 'label');
    addField(option, 'prompt');
    for (const choice of option.choices || []) {
      addField(choice, 'label');
      addField(choice, 'why');
    }
  }

  return fragments;
}

function isPresetJson(relativePath) {
  return /^design\/tokens\/presets\/[^/]+\.json$/u.test(
    normalizePath(relativePath),
  );
}

function extractVisibleFragments(source, relativePath) {
  const extension = path.extname(relativePath);
  if (CODE_EXTENSIONS.has(extension)) {
    return extractCodeFragments(source, relativePath);
  }
  if (isPresetJson(relativePath)) {
    return extractPresetFragments(source, relativePath);
  }
  if (extension === '.md') return extractMarkdownFragments(source);
  if (extension === '.html') return extractHtmlFragments(source);
  return [{ text: source, startLine: 1 }];
}

function sourceLine(source, line) {
  return source.split(/\r?\n/u)[line - 1] ?? '';
}

function linesBefore(text, index) {
  let count = 0;
  for (let cursor = 0; cursor < index; cursor += 1) {
    if (text[cursor] === '\n') count += 1;
  }
  return count;
}

function sourceMatchIndex(sourceText, matchText, startIndex) {
  return sourceText.toLocaleLowerCase('en-US').indexOf(
    matchText.toLocaleLowerCase('en-US'),
    startIndex,
  );
}

function findFindings(source, relativePath, rules = BLOCKED_RULES) {
  if (isExcluded(relativePath)) return [];
  const fragments = extractVisibleFragments(source, relativePath);
  const findings = [];

  for (const fragment of fragments) {
    for (const rule of rules) {
      rule.pattern.lastIndex = 0;
      let sourceSearchFrom = 0;
      for (const match of fragment.text.matchAll(rule.pattern)) {
        let line = fragment.startLine + linesBefore(fragment.text, match.index);
        if (typeof fragment.sourceText === 'string') {
          const sourceIndex = sourceMatchIndex(
            fragment.sourceText,
            match[0],
            sourceSearchFrom,
          );
          if (sourceIndex !== -1) {
            line = fragment.startLine + linesBefore(fragment.sourceText, sourceIndex);
            sourceSearchFrom = sourceIndex + match[0].length;
          }
        }
        findings.push({
          path: relativePath,
          line,
          rule: rule.id,
          match: match[0],
          guidance: rule.guidance,
          excerpt: sourceLine(source, line).trim().replace(/\s+/gu, ' ').slice(0, 180),
        });
      }
    }
  }

  return findings.sort(
    (left, right) => left.line - right.line || left.rule.localeCompare(right.rule),
  );
}

function run() {
  const files = collectFiles();
  const findings = [];

  try {
    for (const relativePath of files) {
      const source = fs.readFileSync(path.join(ROOT, relativePath), 'utf8');
      findings.push(...findFindings(source, relativePath));
    }
  } catch (error) {
    console.error(`copy-style: ${error.message}`);
    process.exitCode = 1;
    return;
  }

  if (findings.length === 0) {
    console.log(`copy-style: checked ${files.length} files; no blocked patterns found.`);
    return;
  }

  console.error(
    `copy-style: found ${findings.length} blocked pattern(s) in ${files.length} files.`,
  );
  for (const finding of findings) {
    console.error(
      `${finding.path}:${finding.line} [${finding.rule}] ${JSON.stringify(finding.match)}\n` +
        `  ${finding.excerpt}\n` +
        `  ${finding.guidance}`,
    );
  }
  process.exitCode = 1;
}

if (require.main === module) run();

module.exports = {
  BLOCKED_RULES,
  collectFiles,
  extractPresetFragments,
  extractVisibleFragments,
  findFindings,
  isExcluded,
};
